-- =========================================================
-- IH2-22 메뉴 구조 관리 — MENU 테이블 재편 기록용 SQL
-- 2026-08-24, SQLGate로 직접 실행/커밋됨 (이 저장소 코드로는 반영되지 않음 — 기록 목적)
-- 원무/진료/진료지원 재편 + "수술" 최상위 신설 + 진료 "검사" 삭제
-- =========================================================

-- [1] 원무 > 접수관리 하위로: 예약관리/입원접수관리/대기관리 재편성 + 응급접수(진료→원무) 이동
UPDATE MENU SET PARENT_MENU_ID = '0a9c3d36-afd2-4750-98e0-73b8e5bcfcd1', SORT_ORDER = 2, UPDATED_AT = SYSDATE WHERE MENU_ID = '80021b9d-c62b-41c6-83d2-481ac906df40'; -- 예약관리
UPDATE MENU SET PARENT_MENU_ID = '0a9c3d36-afd2-4750-98e0-73b8e5bcfcd1', SORT_ORDER = 1, UPDATED_AT = SYSDATE WHERE MENU_ID = '5ec3a9a8-47a2-4b95-8226-9955198223c8'; -- 입원접수관리
UPDATE MENU SET PARENT_MENU_ID = '0a9c3d36-afd2-4750-98e0-73b8e5bcfcd1', SORT_ORDER = 3, UPDATED_AT = SYSDATE WHERE MENU_ID = '86f09042-eee2-45ac-b2a9-e7358022f773'; -- 대기관리
UPDATE MENU SET PARENT_MENU_ID = '0a9c3d36-afd2-4750-98e0-73b8e5bcfcd1', SORT_ORDER = 4, UPDATED_AT = SYSDATE WHERE MENU_ID = '513a899f-c3a5-4e43-9bdd-cc9e3d4b198e'; -- 응급접수 (URL /emergency/reception, 프론트에 준비중 페이지 생성됨)

-- [2] 원무 > 수납관리 하위로: 수납처리/수납통계/공통조회 재편성
UPDATE MENU SET PARENT_MENU_ID = '2c3bdd39-884a-4819-a031-c244a31106dc', SORT_ORDER = 1, UPDATED_AT = SYSDATE WHERE MENU_ID = '846a9535-eed7-4feb-bba8-c3b23a899558'; -- 수납처리
UPDATE MENU SET PARENT_MENU_ID = '2c3bdd39-884a-4819-a031-c244a31106dc', SORT_ORDER = 2, UPDATED_AT = SYSDATE WHERE MENU_ID = '601eb4a3-5b3e-466d-aa47-7ffb45c373c9'; -- 수납통계 및 기준정보
UPDATE MENU SET PARENT_MENU_ID = '2c3bdd39-884a-4819-a031-c244a31106dc', SORT_ORDER = 3, UPDATED_AT = SYSDATE WHERE MENU_ID = '32b70985-18f5-4c82-ad7d-1d8065eb6f02'; -- 공통조회 및 반출

-- [3] 진료 > "검사"(OPD_LABTEST) 삭제 — soft delete, 원래 화면도 없었음
UPDATE MENU SET USE_YN = 'N', UPDATED_AT = SYSDATE WHERE MENU_ID = '21237bb3-42ed-4c84-a818-fe6246ac254a';

-- [4] 진료 > 외래관리 그룹 신설 + 외래진료/외래처방/의뢰관리 하위 이동
