UPDATE MENU SET PARENT_MENU_ID = 'a1e4c2d0-1111-4a1a-9a11-000000000001', SORT_ORDER = 2, UPDATED_AT = SYSDATE WHERE MENU_ID = '926cb1e5-f149-44a0-8e57-70271bf00f64'; -- 외래처방
